import sys
from collections import Counter

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    passwords = input_data[1:n+1]

    freq = Counter(passwords)

    total_pairs = 0
    for s in passwords:
        L = len(s)
        subs = set()
        for i in range(L):
            for j in range(i + 1, L + 1):
                subs.add(s[i:j])

        matches = 0
        for sub in subs:
            if sub in freq:
                matches += freq[sub]

        # Subtrai 1 porque o usuário não pode formar par com ele mesmo
        total_pairs += matches - 1

    print(total_pairs)

if __name__ == '__main__':
    solve()
